questionvariables.text:
/* Randomly select the angle between the ladder and the ground */
theta: 50+5*rand(7);

/* Randomly select the vertical height reached by the ladder */
height: 3+rand(5);

/* Convert the angle from degrees to radians */
theta_rad: theta*%pi/180;

/* Calculate the horizontal distance from the wall */
distance: height/tan(theta_rad);

/* Calculate the ladder length */
ladder_length: height/sin(theta_rad);

/* Calculate the model answer to 1 decimal place */
ta1: round(ladder_length*10)/10;
